(async()=>{const windowHeader=await fetch('/echo').then(r=>r.json()),workerHeader=await new Promise((resolve,reject)=>{const u=URL.createObjectURL(new Blob([`onmessage=async()=>{try{postMessage(await fetch('${location.origin}/echo').then(r=>r.json()))}catch(e){postMessage({error:String(e)})}}`])),w=new Worker(u);w.onmessage=e=>{w.terminate();URL.revokeObjectURL(u);resolve(e.data)};w.onerror=e=>reject(Error(e.message));w.postMessage(null)});return {window:windowHeader,worker:workerHeader}})()
